python3 -c "
from openpyxl import load_workbook
wb = load_workbook('budget.xlsx', data_only=False)
ws = wb['Budget']
print('dimensions:', ws.dimensions, 'max_row:', ws.max_row, 'max_col:', ws.max_column)
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=3):
    for c in row:
        if c.value is not None:
            print(c.coordinate, repr(c.value))
wb2 = load_workbook('budget.xlsx', data_only=True)
ws2 = wb2['Budget']
print('--- cached values ---')
for row in ws2.iter_rows(min_row=1, max_row=ws2.max_row, max_col=3):
    for c in row:
        if c.value is not None:
            print(c.coordinate, repr(c.value))
"
